                var covered=true;var versions=true;foreach(var coding in codings.Values){var members=(set.Resource["concepts"] as JsonArray??[]).OfType<JsonObject>().Where(c=>S(c,"system")==S(coding,"system")&&S(c,"code")==S(coding,"code")&&c["inactive"]?.GetValue<bool>()!=true&&c["abstract"]?.GetValue<bool>()!=true).ToArray();if(members.Length==0||coding["version"] is not null&&!members.Any(c=>S(c,"version")==S(coding,"version"))){covered=false;break;}if(coding["version"] is null)versions=false;}
